userscript.function:

Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(flag) {
    if (flag) {
        doServiceAjax('sepoa.svc.admin.AD_014', 'TRANSACTION', 'doDeleteCode', null, function(so) {
            if (so.status == '1') {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                callFunction('AD_014_3', 'doQuery', []);
            } else {
                Alert(so.msg);
            }
        });
    }
})


formObj.setReadOnly('TYPE', true);
lastItem = item || lastItem;
formObj.setValue('TYPE', lastItem.code);
callFunction(['p', 'p'], 'changeHeaderText', ['b', Sepoa.cache.text.get('AD_014.COMMON_MODULE') + '(' + lastItem.code + ')'])
doServiceAjax('sepoa.svc.admin.AD_014', 'CONNECTION', 'doQueryHeader', null, function(so) {
    if (so.status == '1') {
        formObj.dataMapper(new SepoaFormater(so.result[0]));
        onChange('FLAG', formObj.getValue('FLAG'));
    } else {
        Alert(so.message);
    }
});


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}
Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
    if (result) {
        lastItem.code = formObj.getValue('TYPE');
        doServiceAjax('sepoa.svc.admin.AD_014', 'TRANSACTION', 'doSaveCode', null, function(so) {
            if (so.status == '1') {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                doQuery();
                callFunction('AD_014_3', 'doQuery', [true]);
            } else {
                Alert(so.msg);
            }
        });
    }
});


if (id == 'FLAG') {
    if (value == 'SL') {
        formObj.forEachItem(function(formId, name) {
            if (name.indexOf('TEXT3') == 0) {
                formObj.hideItem(name);
            }
        })
        formObj.hideItem('TEXT5');
    } else {
        formObj.forEachItem(function(formId, name) {
            if (name.indexOf('TEXT3') == 0) {
                formObj.showItem(name);
            }
        })
        formObj.showItem('TEXT5');
    }
}


doServiceAjax('sepoa.svc.common.COMMON', 'CONNECTION', 'getActiveLanguage', void 0, function(so) {
    if (so.status != 1) {
        Alert(so.message);
        return;
    }
    var sf = new SepoaFormater(so.result[0]);

    var dynamicFormArea = [];

    for (var i = 0; i < sf.getRowCount(); i++) {
        dynamicFormArea.push({
            type: "fieldset",
            label: sf.getValue("TEXT1", i),
            blockOffset: "0",
            inputWidth: "auto",
            list: [{
                    type: "input",
                    inputWidth: "474",
                    name: "TEXT1_" + sf.getValue("LANGUAGE", i),
                    label: Sepoa.cache.text.get("AD_014_5.TEXT1")
                },
                {
                    type: "input",
                    name: "TEXT3_" + sf.getValue("LANGUAGE", i),
                    inputWidth: "474",
                    label: Sepoa.cache.text.get("AD_014_5.TEXT3")
                },
                {
                    type: "input",
                    rows: "5",
                    inputWidth: "474",
                    labelWidth: "85",
                    name: "TEXT4_" + sf.getValue("LANGUAGE", i),
                    label: Sepoa.cache.text.get("AD_014_5.TEXT4")
                }
            ]
        });
    }

    //폼 셋팅
    var formOption = [{
            type: "settings",
            position: "label-top",
            labelAlign: "left",
        },
        {
            type: "block",
            width: "auto",
            blockOffset: "0",
            list: [{
                    type: "input",
                    name: "TYPE",
                    inputWidth: "124",
                    label: Sepoa.cache.text.get("AD_014_5.TYPE")
                },
                {
                    type: "newcolumn"
                },
                {
                    type: "select",
                    value: "",
                    name: "FLAG",
                    inputWidth: "270",
                    userdata: {
                        combo: "SL0001,{HOUSE_CODE}#{LANGUAGE}#AD016"
                    },
                    label: Sepoa.cache.text.get("AD_014_5.FLAG")
                }
            ]
        },
        {
            type: "block",
            width: "auto",
            list: [{
                    type: "select",
                    value: "",
                    name: "USE_FLAG",
                    userdata: {
                        combo: "SL0001,{HOUSE_CODE}#{LANGUAGE}#AD004"
                    },
                    inputWidth: "124",
                    label: Sepoa.cache.text.get("AD_014_5.USE_FLAG")
                },
                {
                    type: "newcolumn"
                },
                {
                    type: "input",
                    value: "",
                    name: "TEXT2",
                    inputWidth: "270",
                    label: Sepoa.cache.text.get("AD_014_5.TEXT2")
                }
            ]
        },
        {
            type: "block",
            width: "auto",
            blockOffset: "0",
            list: [{
                type: "select",
                value: "",
                name: "TEXT5",
                userdata: {
                    combo: "SL0001,{HOUSE_CODE}#{LANGUAGE}#AD004"
                },
                inputWidth: "124",
                label: Sepoa.cache.text.get("AD_014_5.TEXT5")
            }]
        }
    ];

    formOption = formOption.concat(dynamicFormArea);

    formObj = $sObject.formObj = new SepoaMultiDhtmlXFormObject(formbox, 'formObj', [formOption], true);
    formObj.enableLiveValidation(true);
    formObj.attachEvent("onChange", onChange);
    formObj.setReadOnly('TYPE', true);
}, false);
